def subtract(a, b):
    # Filter out empty intervals
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    if not b:
        return sorted(a)

    # Sort intervals by start point
    a = sorted(a)
    b = sorted(b)

    # Merge overlapping intervals in b
    b_merged = []
    for start, end in b:
        if b_merged and start <= b_merged[-1][1]:
            # Overlapping or touching, merge
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    result = []

    for a_start, a_end in a:
        current_start = a_start

        # Process each b interval to subtract it from current a interval
        for b_start, b_end in b_merged:
            # b interval is completely after current segment
            if b_start >= a_end:
                break

            # b interval is completely before current segment
            if b_end <= current_start:
                continue

            # b interval overlaps with current segment
            if b_start > current_start:
                # Add the part before b
                result.append([current_start, b_start])

            # Move current_start past the b interval
            current_start = max(current_start, b_end)

        # Add any remaining part of a
        if current_start < a_end:
            result.append([current_start, a_end])

    # Merge touching intervals in result
    if not result:
        return []

    merged_result = [result[0]]
    for start, end in result[1:]:
        if start == merged_result[-1][1]:
            # Touching, merge
            merged_result[-1][1] = end
        else:
            merged_result.append([start, end])

    return merged_result

